# Manually raising an exception when business constraints are violated
def register_voter(name, age_input):
    try:
        age = int(age_input)
        if age < 0:
            raise ValueError("Age cannot be negative")
        if age < 18:
            raise ValueError("Must be at least 18 years old to register")
    except ValueError as error:
        print("Registration Failed for %s: %s" % (name, error))
    else:
        print("Registration Successful: %s is eligible to vote!" % name)
    finally:
        print("Voter status check complete\n")

register_voter("Ananya", "21")  # Valid
register_voter("Kavya", "15")   # Too young (manual raise)
register_voter("Rohan", "-4")   # Negative (manual raise)
register_voter("Suresh", "abc") # Non-numeric (automatic raise)
